{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Gentle, direct collaboration for change</title>
  <meta name="description" content="Practical therapeutic collaboration for adults in {{CITY}}, {{STATE}} — flexible cadence, clear focus, confidential care.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="layout-bold-playful">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="index.html">{{BUSINESS_NAME}}</a>
      <nav class="main-nav">
        <a href="index.html">Home</a>
        <a href="about.html">Who I Am</a>
        <a href="specialties.html">Focus Areas</a>
        <a href="approach.html">How I Work</a>
        <a href="fees.html">Investment</a>
        <a href="faq.html">Questions</a>
        <a class="cta" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
        <a href="contact.html" class="meta">Connect</a>
      </nav>
      <button class="menu-toggle" aria-label="menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO: Mood selector present here -->
    <section class="hero">
      <div class="wrap hero-grid">
        <div class="hero-card">
          <h1 class="title">A calm, useful way forward when things feel thick</h1>
          <p class="lead">Short-term focus, longer-term clarity — tailored to your rhythm. Practical psychotherapeutic work for adults in {{CITY}}, {{STATE}}.</p>

          <div class="mood-block">
            <label class="mood-label">Right now I feel:</label>
            <div class="mood-options" id="mood-hero">
              <button data-key="overwhelmed">Overwhelmed</button>
              <button data-key="stuck">Stuck</button>
              <button data-key="caretaking">Caretaking</button>
              <button data-key="transition">In transition</button>
            </div>
          </div>

          <div class="method-suggestion" id="hero-method">
            <h3 class="method-title">Suggested approach</h3>
            <p class="method-desc">We'll choose a focused plan to create steady steps and reduce the noise. Suggestions will adapt when you choose a mood.</p>
            <a id="hero-cta" class="primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>

        <svg class="pattern" viewBox="0 0 600 400" preserveAspectRatio="none" aria-hidden="true">
          <defs>
            <pattern id="p1" x="0" y="0" width="40" height="40" patternUnits="userSpaceOnUse">
              <rect width="40" height="40" fill="#fffbf8" />
              <circle cx="10" cy="10" r="3" fill="#ffd4c4" />
              <circle cx="30" cy="30" r="3" fill="#e7ffd9" />
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#p1)" />
        </svg>
      </div>
    </section>

    <!-- STORY: clinician voice + confidentiality and scope -->
    <section class="story wrap">
      <h2>How I work in a few sentences</h2>
      <p>I'm a licensed clinician offering a blend of session work and short courses framed around practical change. I collaborate with people to create clearer routines, relational boundaries, and problem-focused plans. I keep care confidential, within clinical scope, and I do not provide emergency services.</p>
      <p class="note">If you are experiencing a crisis or danger, please call local emergency services or the crisis line in your area. For immediate support in the U.S., dial 988. Outside the U.S., contact local emergency services.</p>
    </section>

    <!-- FRAMEWORK: Mood-to-Method repeated with an alternate layout -->
    <section class="framework">
      <div class="wrap">
        <h2>Methods framed around current needs</h2>
        <p class="sub">A short matching process helps us choose a path that fits your time, energy, and goals.</p>

        <div class="framework-grid">
          <aside class="mood-side">
            <label class="mood-label">What describes you now?</label>
            <div id="mood-side" class="mood-options vertical">
              <button data-key="overwhelmed">Overwhelmed — too much at once</button>
              <button data-key="stuck">Stuck — unsure next step</button>
              <button data-key="caretaking">Caretaking — burnt out helping others</button>
              <button data-key="transition">Transition — big life change</button>
            </div>
          </aside>

          <div class="method-panel" id="framework-method">
            <h3 id="fw-title">Pathway: Gentle Structuring</h3>
            <p id="fw-desc">A brief series to sort immediate priorities, experiment with small changes, and build a stable rhythm.</p>
            <div class="method-actions">
              <a id="fw-cta" class="primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
              <a class="secondary" href="approach.html">Learn more about how I work</a>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- OFFERS: Unique program naming and pricing comparator -->
    <section class="offers wrap" id="offers">
      <h2>Programs & Offerings</h2>
      <p class="sub">Options shaped around rhythm and scope — short intensives, ongoing sessions, and package work for targeted goals.</p>

      <div class="pricing-controls">
        <span class="label">View pricing as</span>
        <div class="toggle" id="price-toggle" aria-hidden="true">
          <button id="monthly-btn" class="active">Monthly</button>
          <button id="package-btn">Package</button>
        </div>
      </div>

      <div class="plans-grid">
        <div class="plan" data-monthly="140" data-package="540">
          <h3>Guided Sessions</h3>
          <p class="plan-desc">Weekly individual sessions to steady progress and respond to life as it unfolds.</p>
          <div class="price"><span class="currency">$</span><span class="num" data-current>140</span><span class="term">/session</span></div>
          <a class="plan-cta primary-cta" href="{{PRIMARY_CTA_URL}}">Start guided sessions</a>
        </div>

        <div class="plan" data-monthly="480" data-package="1400">
          <h3>Clarity Intensive</h3>
          <p class="plan-desc">A 4-session focused package to clarify priorities and build a plan for the next 3 months.</p>
          <div class="price"><span class="currency">$</span><span class="num" data-current>480</span><span class="term">/package</span></div>
          <a class="plan-cta primary-cta" href="{{PRIMARY_CTA_URL}}">Inquire about an intensive</a>
        </div>

        <div class="plan" data-monthly="320" data-package="1100">
          <h3>Steady Support</h3>
          <p class="plan-desc">A monthly plan for regular, paced work — useful when you want continuity without long-term commitment.</p>
          <div class="price"><span class="currency">$</span><span class="num" data-current>320</span><span class="term">/mo</span></div>
          <a class="plan-cta primary-cta" href="{{PRIMARY_CTA_URL}}">Discuss steady support</a>
        </div>
      </div>

      <p class="pricing-note">Fees are presented as described and may vary. Insurance coverage is not guaranteed; ask about sliding scale availability.</p>
    </section>

    <!-- TESTIMONIALS -->
    <section class="testimonials wrap">
      <h2>Notes from people I've worked with</h2>
      <div class="quote-grid">
        <blockquote>
          "Clear guidance and a plan that felt possible. I began to notice smaller changes that mattered." 
          <cite>— client, mid-career</cite>
        </blockquote>
        <blockquote>
          "Helpful structure, warm directness, and confidential space to sort through big decisions." 
          <cite>— client, parent</cite>
        </blockquote>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta wrap">
      <h2>Ready to map a next step?</h2>
      <p class="sub">Book a short intake or send a message to see if we're a good fit.</p>
      <div class="cta-actions">
        <a class="primary-cta large" href="book.html">Book an intake</a>
        <a class="secondary" href="contact.html">Send a message</a>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="meta">
        <div>{{BUSINESS_NAME}} — private practice therapy in {{CITY}}, {{STATE}}</div>
        <div>Phone: {{PHONE}} • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>
      <div class="legal">
        <p>Confidentiality: session content is protected within clinical and legal limits. Scope: therapy here is not a substitute for emergency services or legal advice. If you are in immediate danger, contact local emergency services or your country's crisis line.</p>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
