{"path":"assets/css/styles.css","content":"/* Bold playful with minimal poetic tone */
:root{--accent:#ff8c69;--muted:#6b6b6b;--bg:#fffaf6;--card:#ffffff;--border:#f0e6e3;--accent-2:#8fd3a7}
*{box-sizing:border-box}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;line-height:1.45;color:#222;margin:0;background:var(--bg)}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,rgba(255,140,105,0.06),transparent);border-bottom:1px solid var(--border)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:#2b2b2b;text-decoration:none;font-size:20px}
.main-nav a{margin-left:18px;color:var(--muted);text-decoration:none}
.main-nav a.cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px}
.menu-toggle{display:none;background:none;border:none;font-size:18px}
.hero{padding:48px 0;background:linear-gradient(180deg,#fff 40%,#fffaf6)}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:24px;align-items:center}
.hero-card{background:var(--card);padding:26px;border-radius:14px;box-shadow:0 6px 18px rgba(20,20,20,0.06);border:1px solid var(--border)}
.title{margin:0 0 10px;font-size:28px}
.lead{color:var(--muted);margin:0 0 16px}
.mood-block{margin:12px 0}
.mood-label{font-size:13px;color:#5b5b5b;margin-bottom:8px;display:block}
.mood-options button{margin-right:8px;margin-bottom:8px;border-radius:10px;padding:8px 12px;border:1px solid var(--border);background:#fff;cursor:pointer}
.mood-options.vertical button{display:block;width:100%;text-align:left}
.method-suggestion{margin-top:18px}
.method-title{font-size:14px;margin:0 0 6px}
.method-desc{color:var(--muted);margin:0 0 12px}
.primary-cta{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;text-decoration:none;display:inline-block}
.pattern{width:100%;height:220px;border-radius:12px}
.story{padding:28px 0}
.story h2{margin:0 0 8px}
.story .note{color:#8b0000;font-size:13px}
.framework{background:transparent;padding:26px 0}
.framework-grid{display:grid;grid-template-columns:260px 1fr;gap:18px;align-items:start}
.method-panel{background:var(--card);padding:18px;border-radius:12px;border:1px solid var(--border)}
.method-actions .secondary{margin-left:12px;color:var(--muted);text-decoration:none}
.offers{padding:28px 0}
.pricing-controls{display:flex;align-items:center;margin-bottom:14px}
.pricing-controls .label{color:var(--muted);margin-right:12px}
.toggle{background:#fff;border:1px solid var(--border);display:inline-flex;border-radius:999px}
.toggle button{padding:8px 12px;border-radius:999px;border:none;background:transparent;cursor:pointer}
.toggle button.active{background:var(--accent);color:#fff}
.plans-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:12px}
.plan{background:var(--card);padding:18px;border-radius:12px;border:1px solid var(--border)}
.plan h3{margin:0 0 6px}
.plan-desc{color:var(--muted);font-size:14px}
.price{font-weight:700;margin:14px 0;font-size:20px}
.price .num{display:inline-block;min-width:48px;text-align:right}
.plan-cta{display:inline-block;text-decoration:none;padding:8px 12px;border-radius:10px;background:var(--accent);color:#fff}
.pricing-note{font-size:13px;color:var(--muted);margin-top:10px}
.testimonials{padding:26px 0}
.quote-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}
blockquote{background:#fff;padding:16px;border-radius:10px;border:1px solid var(--border);margin:0}
blockquote cite{display:block;margin-top:8px;color:var(--muted);font-size:13px}
.cta{padding:28px 0;text-align:center}
.cta .large{padding:12px 18px;font-size:16px}
.site-footer{border-top:1px solid var(--border);background:linear-gradient(0deg,transparent,#fffaf6);padding:18px}
.site-footer .meta{font-size:14px;color:var(--muted)}
.site-footer .legal{margin-top:8px;font-size:13px;color:var(--muted)}
/* Responsive */
@media(max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .pattern{height:140px}
  .plans-grid{grid-template-columns:1fr}
  .framework-grid{grid-template-columns:1fr}
  .main-nav{display:none}
  .menu-toggle{display:block}
}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // Price toggle
  const monthlyBtn = document.getElementById('monthly-btn');
  const packageBtn = document.getElementById('package-btn');
  const plans = Array.from(document.querySelectorAll('.plan'));

  function animateNumber(el, start, end, duration){
    const startTime = performance.now();
    function step(now){
      const elapsed = Math.min((now - startTime)/duration,1);
      const value = Math.round(start + (end - start) * easeOutCubic(elapsed));
      el.textContent = value;
      if(elapsed < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }
  function easeOutCubic(t){return 1 - Math.pow(1 - t, 3)}

  function setPricing(mode){
    plans.forEach(plan=>{
      const numEl = plan.querySelector('.num[data-current]');
      const from = Number(numEl.textContent.replace(/[^0-9]/g,'')) || 0;
      const to = Number(plan.getAttribute(mode === 'monthly' ? 'data-monthly' : 'data-package')) || 0;
      // update term label
      const term = plan.querySelector('.term');
      if(mode === 'monthly') term.textContent = (plan.getAttribute('data-monthly') && plan.getAttribute('data-monthly') !== '0') ? '/session' : '/mo';
      else term.textContent = '/package';
      animateNumber(numEl, from, to, 550);
    });
  }

  monthlyBtn.addEventListener('click',function(){
    monthlyBtn.classList.add('active');
    packageBtn.classList.remove('active');
    setPricing('monthly');
  });
  packageBtn.addEventListener('click',function(){
    packageBtn.classList.add('active');
    monthlyBtn.classList.remove('active');
    setPricing('package');
  });

  // Initialize pricing using monthly state
  setPricing('monthly');

  // Mood-to-Method mappings
  const methods = {
    overwhelmed:{
      title:'Short burst: Ground & Organize',
      desc:'A compact set of sessions to reduce immediate overload, prioritize tasks, and create simple routines to protect energy.',
      ctaLabel: 'Book a short intake',
      ctaUrl: '{{PRIMARY_CTA_URL}}'
    },
    stuck:{
      title:'Clarity series',
      desc:'A focused plan to identify barriers, test small changes, and map realistic next steps.',
      ctaLabel: 'Start a clarity inquiry',
      ctaUrl: '{{PRIMARY_CTA_URL}}'
    },
    caretaking:{
      title:'Boundaries & Renewal',
      desc:'Work that centers your needs and explores sustainable boundaries to reduce burnout and re-balance responsibilities.',
      ctaLabel: 'Explore boundary work',
      ctaUrl: '{{PRIMARY_CTA_URL}}'
    },
    transition:{
      title:'Transition support',
      desc:'A tailored sequence for navigating change, weighing options, and tending to the practical and emotional parts of transition.',
      ctaLabel: 'Discuss transition planning',
      ctaUrl: '{{PRIMARY_CTA_URL}}'
    }
  };

  function applyMethod(key){
    const heroTitle = document.querySelector('#hero-method .method-title');
    const heroDesc = document.querySelector('#hero-method .method-desc');
    const heroCta = document.getElementById('hero-cta');
    const fwTitle = document.getElementById('fw-title');
    const fwDesc = document.getElementById('fw-desc');
    const fwCta = document.getElementById('fw-cta');

    const m = methods[key] || methods['stuck'];
    // small morph animation
    fadeText(heroTitle, m.title);
    fadeText(heroDesc, m.desc);
    heroCta.textContent = m.ctaLabel;
    heroCta.href = m.ctaUrl;

    fadeText(fwTitle, 'Pathway: ' + m.title);
    fadeText(fwDesc, m.desc);
    fwCta.textContent = m.ctaLabel;
    fwCta.href = m.ctaUrl;
  }

  function fadeText(el, text){
    el.style.opacity = 0;
    setTimeout(()=>{ el.textContent = text; el.style.opacity = 1; }, 220);
  }

  // Bind mood controls (hero and side)
  const moodHero = document.getElementById('mood-hero');
  const moodSide = document.getElementById('mood-side');

  function bindMood(root){
    if(!root) return;
    root.addEventListener('click',function(e){
      const btn = e.target.closest('button[data-key]');
      if(!btn) return;
      const key = btn.getAttribute('data-key');
      // mark active in this group
      Array.from(root.querySelectorAll('button')).forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      applyMethod(key);
    });
  }
  bindMood(moodHero);
  bindMood(moodSide);

  // Small accessibility: close mobile menu
  const menuToggle = document.querySelector('.menu-toggle');
  menuToggle && menuToggle.addEventListener('click', ()=>{
    const nav = document.querySelector('.main-nav');
    if(nav.style.display === 'flex'){ nav.style.display = 'none'; }
    else { nav.style.display = 'flex'; nav.style.flexDirection = 'column'; }
  });

  // set default mood to 'stuck'
  setTimeout(()=>{
    applyMethod('stuck');
    // mark buttons
    const heroDefault = document.querySelector('#mood-hero button[data-key="stuck"]');
    const sideDefault = document.querySelector('#mood-side button[data-key="stuck"]');
    heroDefault && heroDefault.classList.add('active');
    sideDefault && sideDefault.classList.add('active');
  },120);
});
"} 
